mapper.select:
select
mn.* from Sec_Project mn
left join Sec_Info sec on sec.Sec_Id = mn.Sec_Id left join Sec_Entrust se on se.Sec_Id = sec.Sec_Id where se.id = #{id}

select sec.Sec_Name as secName, sec.Sec_Type as secType, sec.Sec_Organize_Form as secOrganizeForm, sec.Sec_Bidding_Type as secBiddingType, sec.Sec_Start_Time as secStartTime, sec.Sec_Bidding_Cycle as secBiddingCycle, sec.Sec_Place as secPlace, sec.Sec_Trading_Place as secTradingPlace, c1.C_Name as seCpyName, c1.C_Abbreviation as seCpyAbbName, c2.C_Name as tendereeName, c2.C_Abbreviation as tendereeAbbName, c3.C_Name as secAgencyName, mn.* from Sec_Entrust mn left join Sec_Info sec on sec.Sec_Id = mn.Sec_Id left join SYS_Company c1 on c1.C_Id = mn.Se_Cpy_Id left join SYS_Company c2 on c2.C_ID = sec.Sec_Tenderee left join SYS_Company c3 on c3.C_ID = sec.Sec_Agency
and mn.Te_Id = #{params.teId}
and mn.State=#{params.state}
and sec.Sec_Type=#{params.secType}
and sec.Sec_Organize_Form=#{params.secOrganizeForm}
and sec.Sec_Bidding_Type=#{params.secBiddingType}
and INSTR(sec.Sec_Trading_Place,#{params.secTradingPlace})
and INSTR(sec.Sec_Place,#{params.secPlace})
and likeCname(#{params.seCpyName},c1.C_Id)=true
and INSTR(c1.C_Name,#{params.seCpyName})
and INSTR(sec.Sec_Name,#{params.secName})
and INSTR(mn.Create_Uname,#{params.createUname})
and INSTR(mn.Se_Pm,#{params.sePm})
and INSTR(mn.Se_Result,#{params.seResult})
and INSTR(mn.Se_Qualification,#{params.seQualification})
and INSTR(mn.Se_Achievement,#{params.seAchievement})
and likeCname(#{params.tendereeName},c2.C_Id)=true
and INSTR(c2.C_Name,#{params.tendereeName})
and mn.Se_Amt>=#{params.seAmtStart}
and mn.Se_Amt<=#{params.seAmtEnd}
and mn.Create_Time>=#{params.createTimeStart}
and mn.Create_Time<=#{params.createTimeEnd}
and sec.Sec_Start_Time>=#{params.secStartTimeStart}
and sec.Sec_Start_Time<=#{params.secStartTimeEnd}
and sec.Sec_Bidding_Cycle>=#{params.secBiddingCycleStart}
and sec.Sec_Bidding_Cycle<=#{params.secBiddingCycleEnd}
and mn.Sec_Id in ( Select sp.Sec_Id from Sec_Project sp left join Pre_Project sppj on sppj.P_ID = sp.P_Id left join SYS_Department dep on sppj.P_Competent_Department = dep.D_Id
and INSTR(dep.D_Name,#{params.pCompetentDepartmentName})
and INSTR(sppj.P_Name,#{params.pName})
)
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Create_Time DESC
